**深度优先搜索（DFS, Depth-First Search）**：

思想：从某顶点出发，访问此顶点，然后从其未访问的邻接点出发深度优先遍历图，直到图中所有和该顶点有路径的顶点都被访问到。若还有顶点未访问，则另选一个未访问的顶点作为起点，重复上述过程。

```cpp
bool visited[100] = {false};  // 访问标记数组

// 递归DFS
void DFS(ALGraph G, int v) {
    cout << G.vertices[v].data;  // 访问v
    visited[v] = true;
    ArcNode* p = G.vertices[v].firstarc;
    while (p) {
        int w = p->adjvex;  // 邻接点w
        if (!visited[w]) DFS(G, w);  // 递归访问未访问邻接点
        p = p->nextarc;
    }
}

// 非递归DFS（用栈）
void DFS_NonRec(ALGraph G, int v) {
    stack<int> S;
    S.push(v); visited[v] = true;
    cout << G.vertices[v].data;
    while (!S.empty()) {
        int x = S.top();
        bool found = false;
        ArcNode* p = G.vertices[x].firstarc;
        while (p) {
            if (!visited[p->adjvex]) {
                visited[p->adjvex] = true;
                cout << G.vertices[p->adjvex].data;
                S.push(p->adjvex);
                found = true;
                break;
            }
            p = p->nextarc;
        }
        if (!found) S.pop();  // 没有未访问邻接点，回溯
    }
}

// 遍历整个图（可能不连通）
void DFSTraverse(ALGraph G) {
    for (int v = 0; v < G.vexnum; v++) visited[v] = false;
    for (int v = 0; v < G.vexnum; v++)
        if (!visited[v]) DFS(G, v);  // 对未访问顶点调用DFS
}
```

**广度优先搜索（BFS, Breadth-First Search）**：

思想：从某顶点出发，依次访问其所有邻接点，再从这些邻接点出发依次访问它们的邻接点，且"先被访问的顶点的邻接点"先于"后被访问的顶点的邻接点"被访问。

```cpp
void BFS(ALGraph G, int v) {
    queue<int> Q;
    cout << G.vertices[v].data;
    visited[v] = true;
    Q.push(v);
    while (!Q.empty()) {
        int x = Q.front(); Q.pop();
        ArcNode* p = G.vertices[x].firstarc;
        while (p) {
            int w = p->adjvex;
            if (!visited[w]) {
                cout << G.vertices[w].data;
                visited[w] = true;
                Q.push(w);
            }
            p = p->nextarc;
        }
    }
}
```

**时间复杂度分析**：
- 邻接矩阵：O(n²)，每个顶点需遍历n个矩阵元素找邻接点
- 邻接表：O(n+e)，每个顶点和每条边各访问一次
- 空间复杂度：O(n)（辅助栈/队列和访问标记数组）

**DFS/BFS生成树**：
- 遍历过程中经过的边 + n个顶点 构成生成树
- DFS生成树  vs  BFS生成树（按层遍历的树）
- 非连通图则得到生成森林

**最小生成树（Minimum Spanning Tree, MST）**：带权连通图中权值总和最小的生成树。

**性质（MST性质/割边性质）**：设 G=(V,E) 是连通网，U 是 V 的一个真子集。若 (u,v) 是一条满足 u∈U, v∈V-U 的边中权值最小的边，则必存在一棵包含边 (u,v) 的最小生成树。

**1. Prim算法（从顶点出发）**：

思想：设 G=(V,E) 是连通网，令 MST 的顶点集合为 U，边集合为 TE。初始 U={u0}，TE={}。重复：在所有 u∈U, v∈V-U 的边中选权值最小的边 (u,v)，将 v 加入 U，边 (u,v) 加入 TE，直到 U=V 为止。

```cpp
// closedge[i].lowcost = min{ cost(u, vi) | u∈U }
// closedge[i].adjvex = u （记录这条最小边在U中的端点）
typedef struct {
    int adjvex;   // U中的邻接顶点
    int lowcost;  // 最小边的权值
} miniedge;
miniedge closedge[100];

void Prim(MGraph G, int u0) {
    // 初始化
    for (int j = 0; j < G.vexnum; j++)
        closedge[j] = {u0, G.arcs[u0][j]};
    closedge[u0].lowcost = 0;  // 标记u0已并入U

    // 选n-1次最小边
    for (int i = 1; i < G.vexnum; i++) {
        // 选当前closedge中lowcost最小的顶点k
        int min_w = INT_MAX, k = -1;
        for (int j = 0; j < G.vexnum; j++)
            if (closedge[j].lowcost != 0 && closedge[j].lowcost < min_w)
                { min_w = closedge[j].lowcost; k = j; }

        cout << closedge[k].adjvex << "-" << k << ": " << min_w;  // 输出边
        closedge[k].lowcost = 0;  // 将k并入U

        // 更新closedge：对新加入的k，检查V-U中各点
        for (int j = 0; j < G.vexnum; j++)
            if (closedge[j].lowcost != 0 && G.arcs[k][j] < closedge[j].lowcost)
                closedge[j] = {k, G.arcs[k][j]};
    }
}
```

时间复杂度：O(n²)（邻接矩阵），适合稠密图。

**2. Kruskal算法（从边出发）**：

思想：将 G 中 n 个顶点看成 n 棵树，共 n 棵树组成的森林。按权值从小到大选择边，若边的两个顶点属于不同的树，则将此边加入 MST 并合并两棵树；否则舍弃此边。重复直到只剩一棵树为止。

```cpp
// 需要：1) 边按权值排序 2) 并查集（判断两顶点是否同树）

typedef struct { int u, v, w; } Edge;
Edge edges[1000];  // 边集合
bool compare(Edge a, Edge b) { return a.w < b.w; }

// 并查集
int parent[100];
int find(int x) {
    while (parent[x] >= 0) x = parent[x];  // 找根
    return x;
}
void union_sets(int x, int y) {
    int xr = find(x), yr = find(y);
    if (xr != yr) parent[xr] = yr;  // 合并
}

void Kruskal(MGraph G) {
    // 初始化：每个顶点为一棵树
    for (int i = 0; i < G.vexnum; i++) parent[i] = -1;
    // 将所有边按权值排序
    sort(edges, edges + G.arcnum, compare);

    int count = 0;  // 已选边数
    for (int i = 0; i < G.arcnum && count < G.vexnum-1; i++) {
        int u = edges[i].u, v = edges[i].v;
        if (find(u) != find(v)) {  // u,v属不同树
            union_sets(u, v);  // 合并
            cout << u << "-" << v << ": " << edges[i].w;
            count++;
        }
    }
}
```

时间复杂度：O(e log e)（排序决定），适合稀疏图。

**两种算法比较**：
| 算法 | 思想 | 时间复杂度 | 适合 |
|------|------|-----------|------|
| Prim | 从顶点扩展 | O(n²) | 稠密图 |
| Kruskal | 按边选择 | O(e log e) | 稀疏图 |

**单源最短路径（Dijkstra算法）**：

问题：给定带权有向图 G 和源点 v0，求从 v0 到 G 中其他各顶点的最短路径。

前提：边上权值为非负值。

思想：贪心策略。设 S 为已求得最短路径的顶点集合，dist[v] 表示当前从 v0 到 v 的最短路径长度。每次从 V-S 中选 dist 最小的顶点 u 加入 S，然后以 u 为中间点，更新其他顶点的 dist。

```cpp
void Dijkstra(MGraph G, int v0, int dist[], int path[]) {
    bool final[100] = {false};  // final[i]=true表示vi已在S中
    // 初始化
    for (int i = 0; i < G.vexnum; i++) {
        dist[i] = G.arcs[v0][i];  // 初始距离
        path[i] = dist[i] < INT_MAX ? v0 : -1;  // 路径记录
    }
    dist[v0] = 0; final[v0] = true;  // v0加入S

    // 选n-1次
    for (int i = 1; i < G.vexnum; i++) {
        // 选V-S中dist最小的u
        int min_w = INT_MAX, u = -1;
        for (int v = 0; v < G.vexnum; v++)
            if (!final[v] && dist[v] < min_w)
                { min_w = dist[v]; u = v; }
        if (u == -1) break;  // 剩余顶点不可达
        final[u] = true;     // u加入S
        // 以u为中间点更新dist
        for (int v = 0; v < G.vexnum; v++)
            if (!final[v] && G.arcs[u][v] < INT_MAX &&
                dist[u] + G.arcs[u][v] < dist[v])
                { dist[v] = dist[u] + G.arcs[u][v]; path[v] = u; }
    }
}
```

时间复杂度：O(n²)。若用优先队列+邻接表可优化到 O((n+e)log n)。

**每对顶点间最短路径（Floyd算法）**：

思想：动态规划。D^(k)[i][j] 表示从 vi 到 vj 的中间顶点序号不大于 k 的最短路径长度。

递推公式：
- D^(-1)[i][j] = G.arcs[i][j]（初始为直接边的权）
- D^(k)[i][j] = min(D^(k-1)[i][j], D^(k-1)[i][k] + D^(k-1)[k][j])

```cpp
void Floyd(MGraph G, int D[][100], int Path[][100]) {
    // 初始化
    for (int i = 0; i < G.vexnum; i++)
        for (int j = 0; j < G.vexnum; j++) {
            D[i][j] = G.arcs[i][j];
            Path[i][j] = D[i][j] < INT_MAX ? i : -1;
        }
    // 以vk为中间点
    for (int k = 0; k < G.vexnum; k++)
        for (int i = 0; i < G.vexnum; i++)
            for (int j = 0; j < G.vexnum; j++)
                if (D[i][k] < INT_MAX && D[k][j] < INT_MAX &&
                    D[i][k] + D[k][j] < D[i][j]) {
                    D[i][j] = D[i][k] + D[k][j];
                    Path[i][j] = Path[k][j];  // 记录路径
                }
}
```

时间复杂度：O(n³)。

**两种方法比较**：
- Dijkstra：单源，O(n²)或O((n+e)log n)，权值需非负
- Floyd：所有点对，O(n³)，可处理负权但不能有负权回路

**特殊情况：无权重（每条边权值为1）的最短路径 = BFS路径长度**

**有向无环图（DAG, Directed Acyclic Graph）**：无环的有向图。

**AOV网（Activity On Vertex Network）**：用顶点表示活动，用弧表示活动间的优先关系。

**拓扑排序**：对有向无环图构造一个顶点的线性序列，使得图中任意一条弧 <vi,vj>，在序列中 vi 一定在 vj 之前。

**算法步骤**：
1. 从有向图中选择一个入度为0的顶点并输出
2. 从图中删除该顶点和所有以它为尾的弧
3. 重复1和2，直到全部顶点均已输出，或图中还有入度非0的顶点（后者说明图中有环）

```cpp
void TopologicalSort(ALGraph G) {
    int indegree[100] = {0};  // 入度数组
    // 统计各顶点入度
    for (int i = 0; i < G.vexnum; i++) {
        ArcNode* p = G.vertices[i].firstarc;
        while (p) { indegree[p->adjvex]++; p = p->nextarc; }
    }
    // 入度为0的顶点入栈
    stack<int> S;
    for (int i = 0; i < G.vexnum; i++)
        if (indegree[i] == 0) S.push(i);

    int count = 0;  // 计数输出顶点数
    while (!S.empty()) {
        int v = S.top(); S.pop();
        cout << G.vertices[v].data << " "; count++;
        // 删除v及其出边，更新入度
        ArcNode* p = G.vertices[v].firstarc;
        while (p) {
            int w = p->adjvex;
            indegree[w]--;
            if (indegree[w] == 0) S.push(w);
            p = p->nextarc;
        }
    }
    if (count < G.vexnum) cout << "有环！";
}
```

时间复杂度：O(n+e)。

**AOE网（Activity On Edge Network）**：用边表示活动（持续时间），顶点表示事件。用于估算工程完成时间。

**关键路径**：从源点（开始事件）到汇点（完成事件）的最长路径。关键路径上的活动称为关键活动。

**求关键路径的步骤**：
1. 求各事件的最早发生时间 ve[k]（从源点到vk的最长路径长度）
   - ve[源点] = 0
   - ve[k] = max{ ve[j] + len(<vj, vk>) }, 对所有以vk为头的弧<vj, vk>
   （按拓扑顺序计算）

2. 求各事件的最迟发生时间 vl[k]（不推迟工期的前提下，vk的最迟发生时间）
   - vl[汇点] = ve[汇点]
   - vl[k] = min{ vl[j] - len(<vk, vj>) }, 对所有以vk为尾的弧<vk, vj>
   （按逆拓扑顺序计算）

3. 求活动 ai（对应弧<vk, vj>，权dut）的最早开始时间 e[i] 和最迟开始时间 l[i]
   - e[i] = ve[k]（活动起点事件的最早发生时间）
   - l[i] = vl[j] - dut（活动终点事件的最迟发生时间减去活动持续时间）

4. 关键活动：e[i] == l[i] 的活动（时间余量为0，不能延迟）

关键路径：由关键活动组成的从源点到汇点的路径。

**注意**：
- 关键路径可能不唯一
- 加快关键活动可以缩短工期，但加快非关键活动不影响工期
- 加快关键活动到一定程度后，它可能不再是关键活动（关键路径改变）

时间复杂度：O(n+e)。

**并查集（Disjoint Set Union / Union-Find）**是一种用于处理不相交集合的合并与查询问题的树形数据结构，是图算法中Kruskal最小生成树算法的核心辅助结构。

**基本操作：**
1. **Find(x)**：查找元素x所属的集合（通常返回集合的代表元/根结点）
2. **Union(x, y)**：将元素x和y所在的两个集合合并为一个

**存储结构——双亲表示法：**
用数组parent[]存储每个元素的双亲位置。根结点的parent为负数（其绝对值为该集合的元素个数）。

```cpp
int parent[N];  // 并查集数组

// 初始化：每个元素自成一个集合
void Init(int n) {
    for (int i = 0; i < n; i++) parent[i] = -1;  // 初始每个元素是根
}

// 朴素查找：找到x所在集合的根
int Find(int x) {
    while (parent[x] >= 0) x = parent[x];  // 一直向上找根
    return x;
}
```

**优化1：路径压缩（Path Compression）**

在Find操作中，将查找路径上的所有结点直接指向根结点，使后续查找更快。

```cpp
// 递归版路径压缩
int Find_Compress(int x) {
    if (parent[x] < 0) return x;  // x是根
    return parent[x] = Find_Compress(parent[x]);  // 路径压缩
}

// 非递归版（两次遍历）
int Find_Compress2(int x) {
    int root = x;
    while (parent[root] >= 0) root = parent[root];  // 找到根
    while (x != root) {  // 再次遍历，将路径上所有结点指向根
        int next = parent[x];
        parent[x] = root;
        x = next;
    }
    return root;
}
```

**优化2：按秩合并（Union by Rank / Size）**

合并时，总是将较小的树合并到较大的树上，避免树退化成链。

```cpp
// 按大小合并（parent[root]的绝对值=集合大小）
void Union_Size(int x, int y) {
    int rx = Find_Compress(x), ry = Find_Compress(y);
    if (rx == ry) return;  // 已在同一集合
    // 确保rx是较大的集合（parent[rx]更小，即绝对值更大）
    if (parent[rx] > parent[ry]) swap(rx, ry);
    parent[rx] += parent[ry];  // 合并大小
    parent[ry] = rx;            // ry指向rx
}

// 按高度合并（根结点存储 -高度 或 -树高）
void Union_Height(int x, int y) {
    int rx = Find_Compress(x), ry = Find_Compress(y);
    if (rx == ry) return;
    if (parent[rx] > parent[ry]) swap(rx, ry);
    if (parent[rx] == parent[ry]) parent[rx]--;  // 高度相同时，合并后高度+1
    parent[ry] = rx;
}
```

**时间复杂度分析：**

同时使用路径压缩和按秩合并后，并查集的操作时间复杂度为**反阿克曼函数 O(α(n))**，其中α(n)增长极其缓慢（对于任何实际n，α(n) ≤ 4），可以视为**近似常数时间 O(1)**。

**并查集在Kruskal算法中的应用：**

Kruskal算法按权值从小到大选择边，需要判断边的两个顶点是否属于同一连通分量（即是否已连通）。
- Find操作：判断两个顶点是否同属一棵树
- Union操作：若不属于同一棵树，将此边加入MST并合并两棵树

```cpp
// Kruskal算法中使用并查集
void Kruskal(int n, vector<Edge>& edges) {
    Init(n);  // 初始化n个独立集合
    sort(edges.begin(), edges.end(), [](Edge a, Edge b) { return a.w < b.w; });
    int total_w = 0, cnt = 0;
    for (auto& e : edges) {
        int ru = Find_Compress(e.u), rv = Find_Compress(e.v);
        if (ru != rv) {  // 不连通，选此边
            Union_Size(ru, rv);
            total_w += e.w;
            cnt++;
            if (cnt == n - 1) break;  // MST已包含n-1条边
        }
    }
}
```

**并查集的其他应用：**
- 判断无向图的连通性
- 检测无向图中的环
- 网络连通性维护
- 朋友圈问题（LeetCode 547）
- 等式方程的可满足性（LeetCode 990）

**总结：** 并查集虽然结构简单，但配合路径压缩和按秩合并后效率极高，是图论中不可或缺的辅助数据结构。

