#include <iostream>
#include <queue>
#include <stack>
using namespace std;

typedef struct ArcNode {
    int adjvex;
    struct ArcNode* nextarc;
} ArcNode;

typedef struct VNode {
    char data;
    ArcNode* firstarc;
} VNode, AdjList[100];

typedef struct {
    AdjList vertices;
    int vexnum, arcnum;
} ALGraph;

bool visited[100] = {false};

// 递归DFS
void DFS(ALGraph& G, int v) {
    cout << G.vertices[v].data << " ";
    visited[v] = true;
    ArcNode* p = G.vertices[v].firstarc;
    while (p) {
        int w = p->adjvex;
        if (!visited[w]) DFS(G, w);
        p = p->nextarc;
    }
}

// 非递归DFS（用栈）
void DFS_NonRec(ALGraph& G, int v) {
    stack<int> S;
    S.push(v); visited[v] = true;
    cout << G.vertices[v].data << " ";
    while (!S.empty()) {
        int x = S.top();
        bool found = false;
        ArcNode* p = G.vertices[x].firstarc;
        while (p) {
            if (!visited[p->adjvex]) {
                visited[p->adjvex] = true;
                cout << G.vertices[p->adjvex].data << " ";
                S.push(p->adjvex);
                found = true;
                break;
            }
            p = p->nextarc;
        }
        if (!found) S.pop();
    }
}

// BFS（用队列）
void BFS(ALGraph& G, int v) {
    queue<int> Q;
    cout << G.vertices[v].data << " ";
    visited[v] = true;
    Q.push(v);
    while (!Q.empty()) {
        int x = Q.front(); Q.pop();
        ArcNode* p = G.vertices[x].firstarc;
        while (p) {
            int w = p->adjvex;
            if (!visited[w]) {
                cout << G.vertices[w].data << " ";
                visited[w] = true;
                Q.push(w);
            }
            p = p->nextarc;
        }
    }
}

// 对非连通图遍历
void DFSTraverse(ALGraph& G) {
    for (int i = 0; i < G.vexnum; i++) visited[i] = false;
    for (int v = 0; v < G.vexnum; v++)
        if (!visited[v]) DFS(G, v);
}

#include <iostream>
#include <climits>
using namespace std;

#define MAX_V 100
int graph[MAX_V][MAX_V];  // 邻接矩阵
int n;  // 顶点数

// Prim算法 O(n²)
void Prim(int start) {
    int key[MAX_V];     // key[i] = vi到当前MST的最小边权
    bool inMST[MAX_V];  // 是否已在MST中
    for (int i = 0; i < n; i++) { key[i] = INT_MAX; inMST[i] = false; }
    key[start] = 0;

    for (int count = 0; count < n; count++) {
        // 选V-S中key最小的顶点
        int u = -1, min_key = INT_MAX;
        for (int v = 0; v < n; v++)
            if (!inMST[v] && key[v] < min_key) { min_key = key[v]; u = v; }
        if (u == -1) break;
        inMST[u] = true;
        cout << "选" << u << "(权" << min_key << ") ";
        // 更新邻接顶点的key
        for (int v = 0; v < n; v++)
            if (!inMST[v] && graph[u][v] < key[v])
                key[v] = graph[u][v];
    }
}

// Dijkstra算法 单源最短路径 O(n²)
void Dijkstra(int src) {
    int dist[MAX_V];     // src到各点的最短距离
    bool final[MAX_V];   // 是否已求得最短路径
    for (int i = 0; i < n; i++) { dist[i] = graph[src][i]; final[i] = false; }
    dist[src] = 0; final[src] = true;

    for (int count = 0; count < n-1; count++) {
        // 选当前未确定顶点中距离最小的
        int u = -1, min_dist = INT_MAX;
        for (int v = 0; v < n; v++)
            if (!final[v] && dist[v] < min_dist) { min_dist = dist[v]; u = v; }
        if (u == -1) break;
        final[u] = true;
        // 以u为中间点更新邻接点
        for (int v = 0; v < n; v++)
            if (!final[v] && graph[u][v] < INT_MAX &&
                dist[u] + graph[u][v] < dist[v])
                dist[v] = dist[u] + graph[u][v];
    }
    // 输出
    for (int i = 0; i < n; i++)
        cout << src << "->" << i << ": " << dist[i] << endl;
}

// Floyd算法 每对点间最短路径 O(n³)
void Floyd() {
    int D[MAX_V][MAX_V];
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            D[i][j] = graph[i][j];

    for (int k = 0; k < n; k++)  // vk为中间点
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                if (D[i][k] < INT_MAX && D[k][j] < INT_MAX &&
                    D[i][k] + D[k][j] < D[i][j])
                    D[i][j] = D[i][k] + D[k][j];
    // 输出D[i][j]...
}
